    mtx[ 1] = 0.0;
    mtx[ 2] = 0.0;
    mtx[ 3] = 0.0;

    mtx[ 4] = 0.0;
    mtx[ 5] = 2.0f / (top - bottom);
    mtx[ 6] = 0.0;
    mtx[ 7] = 0.0;

