  xx-=1;

  while (ju-jl > 1) {
    jm=(ju+jl) >> 1;

    if ((x >= xx[jm] && monotonicity==1) || (x <= xx[jm] && monotonicity==0))
      jl=jm;
    else
      ju=jm;
  }

  if (x == xx[1]) {
    j=1;
  }
  else {
    if (x == xx[n])
      j=n-1;
    else
      j=jl;
  }

  j-=1;

  return j;
}

