spectral_moda(float *x, int n)
{
  float temp[n];
  int i, j, pos_max;
  float max;

  for (i = 0; i < n; i++)
  {
    temp[i] = 0.f;
  }

  for (i = 0; i < n; i++)
  {
    for (j = i; j < n; j++)
    {
      if (x[j] == x[i])
        temp[i]++;
    }
  }

  max = temp[0];
  pos_max = 0;
  for (i = 0; i < n; i++)
  {
    if (temp[i] > max)
