char * do_door( int * door, int * movement, int operation ) {
    if( !operation ) {
            if(!*door && *movement ) {
                *door = 1;
                *movement = 0;
                return "OPEN";
            }
            if(*door && *movement ) {
                *door = 0;
                *movement = 0;
                return "CLOSED";
            }
    }
    if( !*door && !*movement && operation ) {
        *movement = 1;
        return "OPENING";
    }
    if( *door && !*movement && operation ) {
        *movement = 1;
        return "CLOSING";
    }
    if( *door && *movement && operation ) {
        *movement = 0;
        *door = 0;
        return "STOPPED_WHILE_CLOSING";
    }
    if( !*door && *movement && operation ) {
        *movement = 0;
        *door = 1;
        return "STOPPED_WHILE_OPENING";
    }
    return "ERROR";
}

